def mm_to_px(mm):
    return mm * PX_PER_MM


def px_to_mm(px):
    return px / PX_PER_MM


def all_1d_decompositions(total_mm):
    """
    Возвращает все уникальные последовательности из 960 и 640 мм,
    которые точно дают total_mm.
    Порядок учитывается: [960, 640] и [640, 960] — разные раскладки.
    """
    result = set()

    max_parts = total_mm // 640 + 1

    for count in range(1, max_parts + 1):
        for combo in itertools.product((960, 640), repeat=count):
            if sum(combo) == total_mm:
                result.add(combo)

    # Более крупные кабинеты и меньшее число частей показываем раньше.
    return sorted(
        result,
        key=lambda seq: (len(seq), -seq.count(960), seq)
    )


def all_layouts(width_mm, height_mm):
    """
    Все варианты раскладки по X и Y.
    Каждый вариант содержит последовательность ширин колонок и высот рядов.
    """
    x_variants = all_1d_decompositions(width_mm)
    y_variants = all_1d_decompositions(height_mm)

    layouts = []
    for xs in x_variants:
        for ys in y_variants:
            layouts.append((xs, ys))

    return layouts


def representable_cabinet_sizes(limit_mm):
    """Все габариты <= limit_mm, которые точно собираются из 640/960 мм."""
    return [
        value for value in range(320, limit_mm + 1, 320)
        if all_1d_decompositions(value)
    ]


RZD_VALID_WIDTHS = representable_cabinet_sizes(MAX_W_MM)
RZD_VALID_HEIGHTS = representable_cabinet_sizes(MAX_H_MM)


def nearest_value(raw, values):
    if not values:
        return 0
    if raw <= 0:
        return 0
    return min(values, key=lambda v: (abs(v - raw), v))



class ScreenDesigner(BaseTk):
    def __init__(self):
        super().__init__()
        # V20.22: сначала показываем выбор контекста проекта, основное окно не мигает на экране.
        self.project_brand_context = None
        self._last_notebook_tab = None

        self.title(APP_TITLE)
        self.geometry("1240x680")
        self.minsize(1160, 640)

        self.width_mm = 0
        self.height_mm = 0
        self.layouts = []
        self.layout_index = 0
        self.side2_layout_index = 0
        self.saved_screens = []
        self.procurement_records = []
        self.invoices = []
        self.invoice_files = []
        self.invoice_rows = []
        self.project_name = "Новый проект"
        self.current_project_path = None
        now_iso = datetime.now().isoformat(timespec="seconds")
        self.project_metadata = {"created_at": now_iso, "modified_at": now_iso}
        self._project_dirty = False
        self._loading_project_data = False
        self._loading_saved_product = False
        self._active_screen_index = None
        self._active_static_index = None
        self._project_refresh_after_id = None
        self._tooltip_window = None
        self.screen_mode = MODE_RZD

        self._build_ui()
        self._install_project_autosave_traces()
        self._install_global_clipboard_bindings()
        self._configure_train_columns()
        self.notebook.bind("<<NotebookTabChanged>>", self._on_main_notebook_tab_changed, add="+")
        self.protocol("WM_DELETE_WINDOW", self._on_app_close)
        self._draw_grid()
        self._update_results()
        # Windows startup fix:
        # modal Toplevel создаём только после входа Tk в mainloop.
        # Иначе grab/transient могут сработать до отображения окна.
        self.after(150, self._run_startup_choice)

    def _install_global_clipboard_bindings(self):
        """Единые Ctrl+C/X/V/A для всех редактируемых полей Tk/ttk."""
        def handler(event, virtual):
            w=event.widget
            try:
                state=str(w.cget("state"))
                if state in ("disabled","readonly") and virtual in ("<<Paste>>","<<Cut>>"):
                    return None
            except Exception:
                pass
            try:
                if virtual == "<<SelectAll>>":
                    if isinstance(w, (tk.Entry, ttk.Entry, ttk.Combobox, tk.Spinbox)):
                        w.selection_range(0, "end"); w.icursor("end"); return "break"
                    if isinstance(w, tk.Text):
                        w.tag_add("sel", "1.0", "end-1c"); return "break"
                w.event_generate(virtual)
                return "break"
            except Exception:
                return None
        for seq,virt in (("<Control-c>","<<Copy>>"),("<Control-C>","<<Copy>>"),
                         ("<Control-x>","<<Cut>>"),("<Control-X>","<<Cut>>"),
                         ("<Control-v>","<<Paste>>"),("<Control-V>","<<Paste>>"),
                         ("<Control-a>","<<SelectAll>>"),("<Control-A>","<<SelectAll>>")):
            self.bind_all(seq, lambda e, v=virt: handler(e,v), add="+")

    def _configure_train_columns(self):
        """Колонки двигаются последовательно: ширина соседних не растягивается автоматически."""
        for attr in ("components_tree","reference_tree","project_journal_tree"):
            tree=getattr(self,attr,None)
            if tree is None: continue
            try:
                for c in ("#0",)+tuple(tree["columns"]):
                    tree.column(c, stretch=False)
            except Exception:
                pass

    def _on_main_notebook_tab_changed(self, event=None):
        try: current=self.notebook.select()
        except Exception: return
        previous=getattr(self,"_last_notebook_tab",None)
        # Уход с калькулятора/статики снимает связь с сохранённой записью.
        # Поля остаются заполненными, но последующее изменение создаёт новое изделие,
        # пока оператор явно не загрузит запись мышью.
        if previous and previous != current:
            if previous == str(self.designer_tab):
                self._active_screen_index=None
                self._active_led_instance=None
                try:self.saved_tree.selection_remove(self.saved_tree.selection())
                except Exception:pass
            if previous == str(self.static_tab):
                self._active_static_index=None
                try:self.static_saved_tree.selection_remove(self.static_saved_tree.selection())
                except Exception:pass
        self._last_notebook_tab=current

    def _update_led_type_options(self):
        env=self.screen_environment_var.get() if hasattr(self,"screen_environment_var") else "Улица"
        if not hasattr(self,"led_type_combo"): return
        if env == "Улица":
            self.led_type_combo.configure(values=("OD",))
            if self.led_type_var.get() != "OD": self.led_type_var.set("OD")
        else:
            self.led_type_combo.configure(values=("OD","ID"))
            if self.led_type_var.get() not in ("OD","ID"): self.led_type_var.set("OD")

    def _run_startup_choice(self):
        """Запуск стартового окна после старта mainloop (Windows-safe)."""
        try:
            startup_action = self._show_startup_choice()
        except Exception as exc:
            # Не скрываем ошибку: показываем её пользователю и оставляем
            # возможность выбрать проект через простой резервный диалог.
            try:
                import traceback
                log_path = os.path.join(
                    os.path.dirname(os.path.abspath(sys.executable if getattr(sys, "frozen", False) else __file__)),
                    "startup_dialog_error.log"
                )
                with open(log_path, "w", encoding="utf-8") as f:
                    f.write(traceback.format_exc())
            except Exception:
                log_path = None

            try:
                from tkinter import messagebox
                extra = f"\n\nЛог: {log_path}" if log_path else ""
                messagebox.showerror(
                    "Ошибка окна выбора проекта",
                    f"Не удалось открыть графическое окно выбора РЖД/МЦД.\n{exc}{extra}"
                )
            except Exception:
                pass

            startup_action = self._show_startup_choice_fallback()

        if startup_action == "OPEN":
            self.after(80, self._open_project)
        elif startup_action in ("РЖД", "МЦД"):
            self.project_brand_context = startup_action
            self._apply_project_brand_context()

    def _show_startup_choice_fallback(self):
        """Минимальное резервное окно без PIL/логотипов."""
        result = {"value": None}
        dlg = tk.Toplevel(self)
        dlg.title("Выбор проекта")
        dlg.resizable(False, False)

        box = tk.Frame(dlg, padx=28, pady=24)
        box.pack(fill="both", expand=True)
        tk.Label(box, text="С каким проектом работаем?",
                 font=("Arial", 17, "bold")).pack(pady=(0, 18))

        row = tk.Frame(box)
        row.pack()

        def choose(value):
            result["value"] = value
            try:
                dlg.grab_release()
            except Exception:
                pass
            dlg.destroy()

        tk.Button(row, text="РЖД", width=14, height=4,
                  font=("Arial", 16, "bold"),
                  command=lambda: choose("РЖД")).pack(side="left", padx=10)
        tk.Button(row, text="МЦД", width=14, height=4,
                  font=("Arial", 16, "bold"),
                  command=lambda: choose("МЦД")).pack(side="left", padx=10)
        tk.Button(box, text="Открыть сохранённый проект", width=36, height=2,
                  command=lambda: choose("OPEN")).pack(pady=(18, 0))

        dlg.protocol("WM_DELETE_WINDOW", lambda: choose("МЦД"))
        dlg.update_idletasks()
        x = max(0, (dlg.winfo_screenwidth() - dlg.winfo_reqwidth()) // 2)
        y = max(0, (dlg.winfo_screenheight() - dlg.winfo_reqheight()) // 2)
        dlg.geometry(f"+{x}+{y}")
        dlg.deiconify()
        dlg.lift()
        dlg.attributes("-topmost", True)
        dlg.update()
        try:
            dlg.wait_visibility()
            dlg.grab_set()
        except Exception:
            pass
        dlg.focus_force()
        dlg.after(400, lambda: dlg.attributes("-topmost", False) if dlg.winfo_exists() else None)
        self.wait_window(dlg)
        return result["value"]

    def _show_startup_choice(self):
        result={"value":None}
        dlg=tk.Toplevel(self)
        dlg.title("Выбор проекта")
        dlg.transient(self)
        dlg.resizable(False,False)
        box=tk.Frame(dlg,padx=24,pady=22,bg="#f3f3f3"); box.pack(fill="both",expand=True)
        tk.Label(box,text="С каким проектом работаем?",font=("Arial",18,"bold"),bg="#f3f3f3").pack(pady=(0,18))
        row=tk.Frame(box,bg="#f3f3f3"); row.pack()
        def choose(value):
            result["value"]=value
            dlg.destroy()

        def _make_logo_button(parent, *, logo_b64, fallback_text, value):
            # Изображение является самой кнопкой. Фиксированный размер нужен, чтобы
            # логотип всегда заполнял карточку одинаково на Windows/macOS.
            target_w, target_h = 250, 105
            img_obj=None
            try:
                from PIL import Image, ImageTk, ImageOps
                raw=base64.b64decode(logo_b64)
                img=Image.open(io.BytesIO(raw)).convert("RGB")
                # Растягиваем/кадрируем на всю кнопку с сохранением пропорций.
                img=ImageOps.fit(img,(target_w,target_h),method=Image.Resampling.LANCZOS,centering=(0.5,0.5))
                img_obj=ImageTk.PhotoImage(img)
            except Exception:
                img_obj=None

            if not hasattr(self,"_startup_logo_refs"):
                self._startup_logo_refs=[]
            if img_obj is not None:
                self._startup_logo_refs.append(img_obj)
                btn=tk.Button(parent,image=img_obj,command=lambda:choose(value),
                              width=target_w,height=target_h,relief="flat",bd=0,
                              highlightthickness=1,highlightbackground="#c9c9c9",
                              activebackground="white",cursor="hand2",takefocus=1)
            else:
                btn=tk.Button(parent,text=fallback_text,command=lambda:choose(value),
                              width=16,height=4,bg="#D52B1E" if value=="РЖД" else "#CC2037",
                              fg="white",activebackground="#B52319",
                              font=("Arial",16,"bold"),relief="flat",bd=0,cursor="hand2",takefocus=1)
            btn.pack(side="left",padx=10)
            return btn

        _make_logo_button(row,logo_b64=STARTUP_LOGO_RZD_B64,fallback_text="РЖД",value="РЖД")
        _make_logo_button(row,logo_b64=STARTUP_LOGO_MCD_B64,fallback_text="МЦД",value="МЦД")
        tk.Button(box,text="Открыть сохранённый проект",command=lambda:choose("OPEN"),
                  width=38,height=2,font=("Arial",11,"bold")).pack(pady=(18,0))
        dlg.protocol("WM_DELETE_WINDOW", lambda: choose("МЦД"))
        dlg.update_idletasks()
        x=max(0,(dlg.winfo_screenwidth()-dlg.winfo_reqwidth())//2); y=max(0,(dlg.winfo_screenheight()-dlg.winfo_reqheight())//2)
        dlg.geometry(f"+{x}+{y}")
        try:
            dlg.deiconify()
            dlg.lift()
            dlg.attributes("-topmost", True)
            dlg.update()
            dlg.wait_visibility()
            dlg.grab_set()
            dlg.focus_force()
            dlg.after(400, lambda: dlg.attributes("-topmost", False) if dlg.winfo_exists() else None)
        except Exception:
            try:
                dlg.grab_set()
            except Exception:
                pass
        self.wait_window(dlg)
        if result["value"] in ("РЖД","МЦД"):
            self.project_brand_context=result["value"]
        return result["value"]

    def _apply_project_brand_context(self):
        brand=getattr(self,"project_brand_context",None)
        if brand not in ("РЖД","МЦД"): return
        # Сначала возвращаем все кнопки, затем оставляем нужные.
        for b in getattr(self,"screen_mode_buttons",{}).values():
            try:b.pack_forget()
            except Exception:pass
        for b in getattr(self,"static_mode_buttons",{}).values():
            try:b.pack_forget()
            except Exception:pass
        if brand == "РЖД":
            rb=getattr(self,"screen_mode_buttons",{}).get(MODE_RZD)
            if rb: rb.configure(text="РЖД"); rb.pack(side="left",padx=(0,22))
            srb=getattr(self,"static_mode_buttons",{}).get(MODE_RZD)
            if srb:
                srb.configure(text="РЖД")
                srb.pack(side="left",padx=(0,22))
            self.screen_mode_var.set(MODE_RZD); self.static_mode_var.set(MODE_RZD)
        else:
            rb_m=getattr(self,"screen_mode_buttons",{}).get(MODE_MCD)
            rb_c=getattr(self,"screen_mode_buttons",{}).get(MODE_RZD)
            if rb_m: rb_m.configure(text="МЦД"); rb_m.pack(side="left",padx=(0,22))
            if rb_c: rb_c.configure(text="Кабинетный тип"); rb_c.pack(side="left",padx=(0,22))
            srb=getattr(self,"static_mode_buttons",{}).get(MODE_MCD)
            if srb:srb.pack(side="left",padx=(0,22))
            # Для нового МЦД-проекта стартуем с МЦД; загруженный кабинетный экран сам переключит режим при явной загрузке.
            if not getattr(self,"saved_screens",None): self.screen_mode_var.set(MODE_MCD)
            elif self.screen_mode_var.get() not in (MODE_MCD,MODE_RZD): self.screen_mode_var.set(MODE_MCD)
            self.static_mode_var.set(MODE_MCD)
        try:self._on_screen_mode_changed()
        except Exception:pass
        try:self._static_mode_changed()
        except Exception:pass

    def _safe_filename_part(self, value):
        s=str(value or "").strip() or "без_названия"
        s=re.sub(r'[<>:"/\\|?*]+','_',s)
        s=re.sub(r'\s+',' ',s).strip().rstrip('.')
        return s[:90] or "без_названия"

    def _make_print_pdf_path(self, product, copies=1, is_static=False):
        import tempfile
        project=self._safe_filename_part(self.project_name_var.get().strip() or self.project_name)
        prefix=self._safe_filename_part(getattr(self,"project_brand_context",None) or ("РЖД" if product.get("mode")==MODE_RZD else "МЦД"))
        article=self._safe_filename_part(product.get("article","") if is_static else product.get("module_article","") or product.get("screen_article",""))
        qty_suffix=f"_{int(copies)}шт" if int(copies)>1 else ""
        base=f"{project}_{prefix}_{article}{qty_suffix}"
        folder=Path(tempfile.gettempdir())/"LED_Screen_Designer"; folder.mkdir(parents=True,exist_ok=True)
        path=folder/f"{base}.pdf"
        n=2
        while path.exists():
            path=folder/f"{base}_{n}.pdf"; n+=1
        return path

