    def _mcd_is_custom_size(self):
        return (
            hasattr(self, "mcd_size_var")
            and self.screen_mode_var.get() == MODE_MCD
            and self.mcd_size_var.get() == "Нестандарт"
        )

    def _set_mcd_standard_size(self, value=None):
        value = value or self.mcd_size_var.get()
        sizes = {
            "1780×580": (1780, 580),
            "1380×740": (1380, 740),
            "1700×1220": (1700, 1220),
            "2340×1220": (2340, 1220),
        }
        if value in sizes:
            self.width_mm, self.height_mm = sizes[value]
            self.mcd_manual_width_var.set(str(self.width_mm))
            self.mcd_manual_height_var.set(str(self.height_mm))
            self.layout_index = 0
            self.side2_layout_index = 0
            self._redraw_selection()

    def _on_mcd_size_changed(self, event=None):
        if self.screen_mode_var.get() != MODE_MCD:
            return
        if self.mcd_size_var.get() == "Нестандарт":
            self.mcd_manual_frame.pack(fill="x", pady=(0, 8))
            # Tk pack "before" не требуется: блок уже расположен после combobox.
            self.mcd_manual_width_var.set(str(self.width_mm) if self.width_mm else "")
            self.mcd_manual_height_var.set(str(self.height_mm) if self.height_mm else "")
            self.map_help_var.set("МЦД Нестандарт: габариты можно задать на координатном поле или вручную.")
        else:
            if self.mcd_manual_frame.winfo_manager():
                self.mcd_manual_frame.pack_forget()
            self._set_mcd_standard_size()
            self.map_help_var.set("МЦД: выбран стандартный типоразмер; координатное поле зафиксировано.")
        self._update_mode_ui()

    def _on_mcd_manual_dimensions(self, event=None):
        if not self._mcd_is_custom_size():
            return
        try:
            w = int(self.mcd_manual_width_var.get() or 0)
        except ValueError:
            w = 0
        try:
            h = int(self.mcd_manual_height_var.get() or 0)
        except ValueError:
            h = 0
        self.width_mm = max(0, min(MAX_W_MM, w))
        self.height_mm = max(0, min(MAX_H_MM, h))
        self.layout_index = 0
        self.side2_layout_index = 0
        self._redraw_selection()

    def _on_screen_mode_changed(self):
        self.screen_mode = self.screen_mode_var.get()
        self.width_mm = 0
        self.height_mm = 0
        self.layouts = []
        self.layout_index = 0

        if hasattr(self, "mcd_size_host"):
            # Всегда сначала очищаем содержимое host. Сам host остаётся
            # на фиксированном месте сразу под полем артикула.
            self.mcd_size_label.pack_forget()
            self.mcd_size_combo.pack_forget()
            self.mcd_manual_frame.pack_forget()

            if self.screen_mode == MODE_MCD:
                self.mcd_size_label.pack(anchor="w")
                self.mcd_size_combo.pack(fill="x", pady=(3, 6))

                if self.mcd_size_var.get() == "Нестандарт":
                    self.mcd_manual_frame.pack(fill="x", pady=(0, 8))
                else:
                    self._set_mcd_standard_size()

        self._update_mode_ui()
        self._draw_grid()
        self._redraw_selection()
        self._on_side2_option_changed()

