    def _party_letter(self, index):
        letters=list("АБВГДЕЖЗИЙКЛМНПРСТУФХЦЧШЩЪЫЬЭЮЯ")
        n=max(0,int(index)); out=""; base=len(letters)
        while True:
            out=letters[n%base]+out
            n=n//base-1
            if n<0: break
        return out

    def _ensure_screen_instances(self, screen):
        qty=max(1,int(screen.get("quantity",1) or 1))
        instances=screen.get("instances")
        if not isinstance(instances,list): instances=[]
        base_series=str(screen.get("led_series",screen.get("firmware","")) or "")[:3]
        base_part="".join(ch for ch in str(screen.get("part_number","") or "") if ch.isdigit())
        while len(instances)<qty:
            j=len(instances)
            instances.append({"part_number":base_part if (qty==1 or j==0) else "","led_series":base_series})
        instances=instances[:qty]
        for inst in instances:
            inst.setdefault("part_number",""); inst.setdefault("led_series",base_series)
        screen["instances"]=instances
        return instances

    def _instance_mark(self, group_index, instance_index):
        return f"{group_index+1}.{self._party_letter(instance_index)}"

    def _save_active_instance_overrides(self):
        active=getattr(self,"_active_led_instance",None)
        if not active:return
        try:
            gi,ii=active; screen=self.saved_screens[gi]; inst=self._ensure_screen_instances(screen)[ii]
            inst["part_number"]="".join(ch for ch in self.part_number_var.get() if ch.isdigit())
            inst["led_series"]="".join(ch for ch in self.led_series_var.get() if ch.isdigit())[:3]
            screen["part_number"] = inst["part_number"]
            if hasattr(self,"project_journal_tree"):
                parent_iid=f"led:{gi}"
                if self.project_journal_tree.exists(parent_iid):
                    vals=list(self.project_journal_tree.item(parent_iid,"values"))
                    if len(vals)>=7:
                        vals[4]=inst["part_number"]; vals[6]=inst["led_series"]
                        self.project_journal_tree.item(parent_iid,values=vals)
                iid=f"ledinst:{gi}:{ii}"
                if self.project_journal_tree.exists(iid):
                    vals=list(self.project_journal_tree.item(iid,"values"))
                    if len(vals)>=7:
                        vals[4]=inst["part_number"]; vals[6]=inst["led_series"]
                        self.project_journal_tree.item(iid,values=vals)
        except Exception: pass

    def _screen_weight_kg(self, screen):
        """Вес изделия без упаковки по актуальному справочнику."""
        if screen.get("mode", MODE_RZD) == MODE_MCD:
            one=dict(screen); one["quantity"]=1
            rows=self._dynamic_mcd_component_rows_v1972([one])
            unit_g={
                "Резиновое  уплотнение модуля":21,"Блок питания 200Вт 4,5В 40А":155,
                "Приёмная карта NovaStar MRV":115,"Площадки под МРВ мцд":155,
                "площадка под вентилятор мцд":177,"Вентилятор с решеткой":161,
                "Термодатчик на кулер":42,"карта MSD":105,"площадка под MSD МЦД":155,
                "мини-пк Rassberry pi":100,"площадка под мини-пк МЦД":155,
                "провод питания мини-пк ПугВ-0,3 синий/черн":4,"провод питания мини-пк ПугВ-0,3 красный":4,
                "наконечник питания мини-ПК BLS1":5,"пластина соединительная СТ3":100,
                "Площадки под блоки мцд":174,"Din рейка":20,"уголок алюминиевый 40х20х2":313,
                "Кабель ВВГ 3*1,5":150,"Кабель ШВВП 2*0,75":30,"ПВС 3*1,5":135,
                "Наконечник 0,75":3,"Наконечник 1,5":10,"клеммная колодка 3 винтовая":50,
                "UTP заводские 1м indoor":40,"UTP заводские 1.5м indoor":45,"провод DVI-HDMI":110,
                "переходник HDMI - Микро HDMI":10,"Заклепка 4.8*12":90,"Заклепка резьбовая М6":4,
                "винт М6х25 потай":5.4,"винт M5х80":10.2,"гайка М5 нейлон":0.15,"винт м5х12":2.5,
                "Заклепка резьбовая М3":0.9,"Заклепка резьбовая М4":1,"Винт М3х6":0.5,
                "Саморез ПШ со сверлом 4,2х13":1,"Гайка М4 с нейлоном":1,"Винт полусфера М4*30":1,
                "Винт полусфера М4*20":1,"шайба М4 увелич поле":1,"заклепка резьбовая М5":2,
                "Болт внутр шестигранник 5х20":2,"шайба уплот кровельная 4,8х14":1,
                "заглушка декоротивная 16":1,"силикон герметик":1,"втулка винипласт":2,
                "Скотч двухсторонний 3M":18,"Уплотнитель МЦД":20}
            module_g={"LED-модуль P 2.5 IN":414,"LED-модуль P 2.5 OD":416,"LED-модуль P1.53 OD":433,
                      "LED-модуль P4.0 IN":340,"LED-модуль P4.0 OD":430,"LED-модуль P5.0 OD":429,"LED-модуль P3,07 OD":425}
            total=0.0; mod=self._selected_led_module_name(one)
            for name,unit,qty in rows:
                q=float(qty) if isinstance(qty,(int,float)) else 0.0
                if name==mod and mod in module_g: total+=q*module_g[mod]
                elif str(name).startswith("Профиль 175мм"):
                    total+=(2*(float(one.get("width",0))+float(one.get("height",0)))/1000.0)*3880
                elif str(name).startswith("Оргстекло 8 мм"):
                    gw=max(0,float(one.get("width",0))-18)/1000; gh=max(0,float(one.get("height",0))-18)/1000; total+=gw*gh*9520*q
                elif str(name).startswith(("Алюкобонд 3 мм","Алюкобонд 4 мм")):
                    aw=max(0,float(one.get("width",0))-52)/1000; ah=max(0,float(one.get("height",0))-52)/1000; total+=aw*ah*7600*q
                elif name in unit_g: total+=q*unit_g[name]
            return total/1000.0 if total else None
        if screen.get("mode", MODE_RZD) != MODE_RZD:
            return None
        module_name = self._selected_led_module_name(screen)
        counts = screen.get("counts", {}) or {}
        sides = max(1, int(screen.get("sides", 1) or 1))
        total_grams = 0.0
        for size, count in counts.items():
            size_key = tuple(size) if isinstance(size, (tuple, list)) else size
            lookup_size = (960,640) if size_key == (640,960) else size_key
            data = CABINET_WEIGHT_DATA_V19_71.get(lookup_size)
            if not data or not count: continue
            module_weight = data["module_weights"].get(module_name)
            if module_weight is None: return None
            total_grams += (data["fixed_grams"] + data["module_qty"] * module_weight) * float(count) * sides
        # V20.22: +4 наконечника 0,75 × 3 г только на динамическое изделие РЖД.
        total_grams += 12.0
        return total_grams / 1000.0

    def _static_sign_weight_kg(self, sign):
        """Вес статического МЦД/РЖД по фактическому BOM и весам справочника."""
        mode=sign.get("mode")
        face=sign.get("face_type")
        if mode==MODE_MCD:
            if face!="С подсветкой":
                return None
            rows=self._static_mcd_component_rows([sign])
        elif mode==MODE_RZD:
            rows=self._static_rzd_component_rows([sign])
        else:
            return None
        total=0.0; found=False
        for name,unit,qty in rows:
            w=self._component_weight_kg(name,unit,qty)
            if w is not None:
                total+=w; found=True
        return total if found else None

    def _format_static_sign_weight(self, sign):
        value=self._static_sign_weight_kg(sign)
        return "—" if value is None else f"{value:.2f}".replace(".",",")

    def _format_screen_weight(self, screen):
        value = self._screen_weight_kg(screen)
        return "—" if value is None else f"{value:.2f}".replace(".", ",")

    def _refresh_project_journal(self):
        if not hasattr(self,"project_journal_tree"):return
        opened={iid for iid in self.project_journal_tree.get_children()
                if iid.startswith("led:") and self.project_journal_tree.item(iid,"open")}
        for iid in self.project_journal_tree.get_children():self.project_journal_tree.delete(iid)
        n=1
        for i,s in enumerate(self.saved_screens):
            mode=s.get("mode",MODE_RZD); execution=mode
            if getattr(self,"project_brand_context",None)=="МЦД" and mode==MODE_RZD:
                execution="Кабинетный тип"
            if mode==MODE_MCD and s.get("mcd_size"):execution=f"МЦД / {s.get('mcd_size')}"
            instances=self._ensure_screen_instances(s); parent=f"led:{i}"
            serial = instances[0].get("part_number","") if instances else s.get("part_number","")
            self.project_journal_tree.insert("","end",iid=parent,open=(parent in opened),values=(
                n,"LED-экран",s.get("screen_article",""),s.get("module_article",""),serial,"","",
                f"{s.get('width',0)} × {s.get('height',0)}",self._format_screen_weight(s),s.get("sides",1),execution))
            if len(instances)>1:
                for j,inst in enumerate(instances):
                    self.project_journal_tree.insert(parent,"end",iid=f"ledinst:{i}:{j}",values=(
                        "","Экземпляр",s.get("screen_article",""),s.get("module_article",""),
                        inst.get("part_number",""),self._instance_mark(i,j),inst.get("led_series",""),
                        f"{s.get('width',0)} × {s.get('height',0)}",self._format_screen_weight(s),s.get("sides",1),execution))
            n+=1
        for i,s in enumerate(getattr(self,"saved_static_signs",[])):
            shape="Круглый" if s.get("round",False) else s.get("face_type","")
            size=f"Ø {s.get('width',0)}" if s.get("round",False) else f"{s.get('width',0)} × {s.get('height',0)}"
            self.project_journal_tree.insert("","end",iid=f"static:{i}",values=(
                n,"Статический указатель",s.get("name",""),s.get("article",""),"","","",size,self._format_static_sign_weight(s),
                s.get("sides",1),f"{s.get('mode',MODE_MCD)} / {shape}")); n+=1

    def _open_project_journal_item(self,event=None):
        sel=self.project_journal_tree.selection()
        if not sel:return
        iid=sel[0]
        if iid.startswith("ledinst:"):
            if not bool(getattr(self, "project_journal_edit_var", tk.BooleanVar(value=False)).get()):
                return
            _,gi,ii=iid.split(":"); gi=int(gi); ii=int(ii)
            if gi>=len(self.saved_screens):return
            screen=self.saved_screens[gi]; instances=self._ensure_screen_instances(screen)
            if ii>=len(instances):return
            self._active_led_instance=None
            self.notebook.select(self.designer_tab)
            self.saved_tree.selection_set(str(gi)); self.saved_tree.focus(str(gi)); self._load_saved_screen()
            self._active_led_instance=(gi,ii)
            self.part_number_var.set(instances[ii].get("part_number",""))
            self.led_series_var.set(instances[ii].get("led_series",screen.get("led_series","")))
            return
        if iid.startswith("led:"):
            idx=int(iid.split(":",1)[1])
            if idx>=len(self.saved_screens):return
            if max(1,int(self.saved_screens[idx].get("quantity",1) or 1))>1:
                self.project_journal_tree.item(iid,open=not bool(self.project_journal_tree.item(iid,"open"))); return
            if not bool(getattr(self, "project_journal_edit_var", tk.BooleanVar(value=False)).get()):
                return
            self._active_led_instance=None
            self.notebook.select(self.designer_tab)
            self.saved_tree.selection_set(str(idx)); self.saved_tree.focus(str(idx)); self._load_saved_screen()
            inst=self._ensure_screen_instances(self.saved_screens[idx])[0]
            self._active_led_instance=(idx,0)
            self.part_number_var.set(inst.get("part_number",""))
            self.led_series_var.set(inst.get("led_series",self.saved_screens[idx].get("led_series","")))
        elif iid.startswith("static:"):
            if not bool(getattr(self, "project_journal_edit_var", tk.BooleanVar(value=False)).get()):
                return
            self._active_led_instance=None
            idx=int(iid.split(":",1)[1])
            if idx>=len(getattr(self,"saved_static_signs",[])):return
            self.notebook.select(self.static_tab)
            self.static_saved_tree.selection_set(str(idx)); self.static_saved_tree.focus(str(idx))
            self._load_selected_static_sign()

    def _on_project_name_changed(self, *args):
        if hasattr(self, "project_name_var"):
            new_name = self.project_name_var.get().strip() or "Новый проект"
            changed = (new_name != getattr(self, "project_name", "Новый проект"))
            self.project_name = new_name
            if changed and not getattr(self, "_loading_project_data", False):
                self._mark_project_dirty()

    def _mark_project_dirty(self):
        if getattr(self, "_loading_project_data", False):
            return
        self._project_dirty = True
        if not isinstance(getattr(self, "project_metadata", None), dict):
            self.project_metadata = {}
        self.project_metadata.setdefault("created_at", datetime.now().isoformat(timespec="seconds"))
        self.project_metadata["modified_at"] = datetime.now().isoformat(timespec="seconds")

    def _install_project_autosave_traces(self):
        # Изменения загруженного изделия сразу записываются в его словарь в памяти проекта.
        screen_vars = (
            "screen_mode_var","screen_article_var","module_article_var","part_number_var",
            "screen_environment_var","pixel_pitch_var","led_type_var","led_series_var",
            "control_type_var","media_converter_var","optical_cross_var","chip_var",
            "card_model_var","support_var","screen_quantity_var","screen_sides_var",
            "mcd_size_var","side2_different_layout_var"
        )
        static_vars = (
            "static_mode_var","static_name_var","static_article_var","static_layout_no_var",
            "static_round_var","static_sides_var","static_face_type_var","static_profile_var",
            "static_frame_profile_var","static_mount_type_var","static_quantity_var","static_autofill_var"
        )
        for attr in screen_vars:
            var=getattr(self,attr,None)
            if var is not None:
                try: var.trace_add("write", self._on_active_screen_field_changed)
                except Exception: pass
        for attr in static_vars:
            var=getattr(self,attr,None)
            if var is not None:
                try: var.trace_add("write", self._on_active_static_field_changed)
                except Exception: pass

    def _on_active_screen_field_changed(self, *args):
        if not getattr(self, "_loading_saved_product", False):
            self._sync_active_screen_from_form()

    def _on_active_static_field_changed(self, *args):
        if not getattr(self, "_loading_saved_product", False):
            self._sync_active_static_from_form()

    def _schedule_project_views_refresh(self):
        try:
            if self._project_refresh_after_id is not None:
                self.after_cancel(self._project_refresh_after_id)
        except Exception:
            pass
        try:
            self._project_refresh_after_id = self.after(180, self._refresh_views_after_autosave)
        except Exception:
            self._project_refresh_after_id = None

    def _refresh_views_after_autosave(self):
        self._project_refresh_after_id = None
        try: self._refresh_project_journal()
        except Exception: pass
        try: self._refresh_components_screen_selector()
        except Exception: pass
        try: self._refresh_components_table()
        except Exception: pass

    def _sync_active_static_from_form(self):
        idx=getattr(self,"_active_static_index",None)
        signs=getattr(self,"saved_static_signs",[])
        if idx is None or not (0 <= idx < len(signs)) or getattr(self,"_loading_saved_product",False):
            return
        s=signs[idx]
        try: sides=int(self.static_sides_var.get() or 1)
        except Exception: sides=1
        mode=self.static_mode_var.get()
        updated={
            "name":self.static_name_var.get().strip(),
            "article":self.static_article_var.get().strip(),
            "layout_no":self.static_layout_no_var.get().strip(),
            "mode":mode,"width":int(self.static_width_mm or 0),"height":int(self.static_height_mm or 0),
            "sides":max(1,min(2,sides)),"profile":self.static_profile_var.get(),
            "frame_profile":self.static_frame_profile_var.get(),
            "mount_type":self.static_mount_type_var.get() if mode==MODE_RZD else "",
            "quantity":self.static_quantity_var.get().strip() if mode in (MODE_MCD,MODE_RZD) else "",
            "autofill":bool(self.static_autofill_var.get()) if mode==MODE_RZD else False,
            "face_type":self.static_face_type_var.get(),
            "round":bool(self.static_round_var.get()) if mode==MODE_MCD else False,
            "diameter":(int(self.static_width_mm or 0) if mode==MODE_MCD and self.static_round_var.get() else "")
        }
        changed=any(s.get(k)!=v for k,v in updated.items())
        if not changed:
            return
        s.update(updated)
        self._mark_project_dirty()
        try:
            if self.static_saved_tree.exists(str(idx)):
                self.static_saved_tree.item(str(idx),values=(idx+1,s.get("name") or s.get("article") or f"Указатель {idx+1}",f"{s.get('width',0)} × {s.get('height',0)}",s.get("sides",1)))
        except Exception: pass
        self._schedule_project_views_refresh()

    def _sync_active_screen_from_form(self):
        idx=getattr(self,"_active_screen_index",None)
        screens=getattr(self,"saved_screens",[])
        if idx is None or not (0 <= idx < len(screens)) or getattr(self,"_loading_saved_product",False):
            return
        sc=screens[idx]
        mode=self.screen_mode_var.get()
        try: quantity=max(1,int(self.screen_quantity_var.get() or 1))
        except Exception: quantity=1
        try: sides=max(1,min(2,int(self.screen_sides_var.get() or 1)))
        except Exception: sides=1
        w=int(self.width_mm or 0); h=int(self.height_mm or 0)
        counts={(960,960):0,(960,640):0,(640,960):0,(640,640):0}
        width_parts=(); height_parts=(); cabinet_total=0; module_total=0
        module_field_w=w; module_field_h=h
        layout_index=int(getattr(self,"layout_index",0) or 0)
        if mode==MODE_RZD and w and h:
            layouts=all_layouts(w,h)
            if layouts:
                layout_index=min(layout_index,len(layouts)-1)
                width_parts,height_parts=layouts[layout_index]
                nw960,nw640=width_parts.count(960),width_parts.count(640)
                nh960,nh640=height_parts.count(960),height_parts.count(640)
                counts={(960,960):nw960*nh960,(960,640):nw960*nh640,(640,960):nw640*nh960,(640,640):nw640*nh640}
                cabinet_total=sum(counts.values())
            module_total=(w//MODULE_W)*(h//MODULE_H) if w and h else 0
        elif mode==MODE_MCD and w and h:
            if self._mcd_is_custom_size():
                mc=max(0,w//MCD_MODULE_W); mr=max(0,h//MCD_MODULE_H)
                module_field_w=mc*MCD_MODULE_W; module_field_h=mr*MCD_MODULE_H; module_total=mc*mr
            else:
                module_field_w=w-2*MCD_MARGIN; module_field_h=h-2*MCD_MARGIN
                module_total=max(0,module_field_w//MCD_MODULE_W)*max(0,module_field_h//MCD_MODULE_H)
        updated={
            "screen_article":self.screen_article_var.get().strip(),"module_article":self.module_article_var.get().strip(),
            "part_number":self.part_number_var.get(),"environment":self.screen_environment_var.get(),
            "pixel_pitch":self.pixel_pitch_var.get(),"led_type":self.led_type_var.get(),
            "led_series":self.led_series_var.get(),"control_type":self.control_type_var.get(),
            "media_converter":bool(self.media_converter_var.get()),"optical_cross":bool(self.optical_cross_var.get()),
            "chip":self.chip_var.get().strip(),"card_model":self.card_model_var.get().strip() or "MRV416-N",
            "firmware":self.firmware_var.get().strip(),"support":self.support_var.get().strip(),
            "mode":mode,"mcd_size":(self.mcd_size_var.get() if mode==MODE_MCD else ""),
            "quantity":quantity,"sides":sides,"width":w,"height":h,
            "module_field_width":module_field_w,"module_field_height":module_field_h,
            "layout_index":layout_index,"side2_layout_index":int(getattr(self,"side2_layout_index",0) or 0),
            "side2_different_layout":bool(self.side2_different_layout_var.get()),
            "cabinet_total":cabinet_total,"module_total":module_total,"counts":counts,
            "width_parts":tuple(width_parts),"height_parts":tuple(height_parts)
        }
        changed=any(sc.get(k)!=v for k,v in updated.items())
        if not changed:
            return
        sc.update(updated)
        old_instances=list(sc.get("instances",[]) or [])
        while len(old_instances)<quantity:
            old_instances.append({"part_number":"","led_series":self.led_series_var.get()})
        sc["instances"]=old_instances[:quantity]
        self._mark_project_dirty()
        try:
            if self.saved_tree.exists(str(idx)):
                factor=quantity*sides
                cab_disp=cabinet_total*factor if mode==MODE_RZD else "—"
                self.saved_tree.item(str(idx),values=(idx+1,sc.get("screen_article",""),f"{w}×{h}",quantity,sides,cab_disp))
        except Exception: pass
        self._schedule_project_views_refresh()

    def _confirm_unsaved_project(self):
        if not getattr(self,"_project_dirty",False):
            return True
        answer=messagebox.askyesnocancel(
            "Несохранённые изменения",
            "Проект был изменён.\n\nСохранить изменения перед выходом?"
        )
        if answer is None:
            return False
        if answer:
            return bool(self._save_project(quiet=True))
        return True

    def _on_app_close(self):
        phrases = [
            "Ты устал или действительно решил на сегодня всё?",
            "Уже домой? Проверим, точно закрываем?",
            "Крестик нажат уверенно. Закрываем программу?",
            "Рабочий день официально закончен или это случайный клик?",
            "Проект отпускаем отдыхать?",
            "Точно закрыть, а не просто потянуться к правому верхнему углу?",
            "Все экраны посчитаны и можно расходиться?",
            "Закрываем цех калькуляций на сегодня?",
            "Оператор покидает пост? Подтвердить закрытие?",
            "Пора выключать свет? Закрываем программу?",
            "Это осознанное закрытие или мышь решила сама?",
            "Финальный аккорд? Закрыть приложение?",
            "Все проверено дважды? Тогда закрываем?",
            "Программа спрашивает: ты точно закончил?",
            "Последний шанс перед выходом — закрыть программу?",
        ]
        if not messagebox.askyesno("Закрытие программы", random.choice(phrases) + "\n\nЗакрыть программу?"):
            return
        if not self._confirm_unsaved_project():
            return
        self.destroy()

    def _force_module_article_upper(self, *args):
        if getattr(self, "_module_article_upper_guard", False):
            return
        value = self.module_article_var.get()
        upper = value.upper()
        if value != upper:
            self._module_article_upper_guard = True
            self.module_article_var.set(upper)
            self._module_article_upper_guard = False

    def _add_to_project(self):
        w = self.width_mm
        h = self.height_mm
        mode = self.screen_mode_var.get()

        screen_article = self.screen_article_var.get().strip()
        module_article = self.module_article_var.get().strip()

        try:
            quantity = max(1, int(self.screen_quantity_var.get()))
            sides = max(1, min(2, int(self.screen_sides_var.get())))
        except ValueError:
            self._flash_project_button("Проверьте количество и стороны")
            return

        if not (w and h):
            self._flash_project_button("Сначала выберите экран")
            return
        if not screen_article:
            self._flash_project_button("Укажите артикул LED-экрана")
            self.screen_article_entry.focus_set()
            return
        if not module_article:
            self._flash_project_button("Укажите артикул LED-модуля")
            self.module_article_entry.focus_set()
            return

        counts = {(960, 960): 0, (960, 640): 0, (640, 960): 0, (640, 640): 0}
        width_parts = ()
        height_parts = ()
        cabinet_total = 0
        layout_index = 0

        if mode == MODE_RZD:
            layouts = all_layouts(w, h)
            if not layouts:
                self._flash_project_button("Нет допустимой раскладки")
                return
            layout_index = min(self.layout_index, len(layouts) - 1)
            width_parts, height_parts = layouts[layout_index]
            nw960, nw640 = width_parts.count(960), width_parts.count(640)
            nh960, nh640 = height_parts.count(960), height_parts.count(640)
            counts = {
                (960, 960): nw960 * nh960,
                (960, 640): nw960 * nh640,
                (640, 960): nw640 * nh960,
                (640, 640): nw640 * nh640,
            }
            cabinet_total = sum(counts.values())
            module_total = (w // MODULE_W) * (h // MODULE_H)
            module_field_w, module_field_h = w, h
        elif mode == MODE_MCD:
            if self._mcd_is_custom_size():
                module_cols=max(0,int(w)//MCD_MODULE_W)
                module_rows=max(0,int(h)//MCD_MODULE_H)
                module_field_w=module_cols*MCD_MODULE_W
                module_field_h=module_rows*MCD_MODULE_H
                module_total=module_cols*module_rows
            else:
                module_field_w = w - 2 * MCD_MARGIN
                module_field_h = h - 2 * MCD_MARGIN
                module_total = (module_field_w // MCD_MODULE_W) * (module_field_h // MCD_MODULE_H)
        else:
            module_field_w, module_field_h = w, h
            module_total = (w // MODULE_W) * (h // MODULE_H)

        screen = {
            "screen_article": screen_article,
            "module_article": module_article,
            "part_number": self.part_number_var.get(),
            "environment": self.screen_environment_var.get(),
            "pixel_pitch": self.pixel_pitch_var.get(),
            "led_type": self.led_type_var.get(),
            "led_series": self.led_series_var.get(),
            "control_type": self.control_type_var.get(),
            "media_converter": bool(self.media_converter_var.get()),
            "optical_cross": bool(self.optical_cross_var.get()),
            "chip": self.chip_var.get().strip(),
            "card_model": self.card_model_var.get().strip() or "MRV416-N",
            "firmware": self.firmware_var.get().strip(),
            "support": self.support_var.get().strip(),
            "mode": mode,
            "mcd_size": (self.mcd_size_var.get() if mode == MODE_MCD else ""),
            "quantity": quantity,
            "sides": sides,
            "width": w,
            "height": h,
            "module_field_width": module_field_w,
            "module_field_height": module_field_h,
            "layout_index": layout_index,
            "side2_layout_index": self.side2_layout_index,
            "side2_different_layout": bool(self.side2_different_layout_var.get()),
            "cabinet_total": cabinet_total,
            "module_total": module_total,
            "counts": counts,
            "width_parts": tuple(width_parts),
            "height_parts": tuple(height_parts),
        }
        screen["instances"]=[{"part_number":(self.part_number_var.get() if (quantity==1 or j==0) else ""),
                              "led_series":self.led_series_var.get()} for j in range(quantity)]
        self.saved_screens.append(screen)
        self._active_led_instance=None
        self._mark_project_dirty()

        number = len(self.saved_screens)
        factor = quantity * sides
        cabinet_display = cabinet_total * factor if mode == MODE_RZD else "—"
        self.saved_tree.insert(
            "", "end", iid=str(number - 1),
            values=(number, screen_article, f"{w}×{h}", quantity, sides, cabinet_display)
        )

        self._refresh_project_journal()
        self._refresh_components_screen_selector()
        self._refresh_components_table()
        self._refresh_stock_screen_selector()
        self._refresh_procurement_table()

        # После добавления изделия координатное поле сразу переходит
        # к префиксу следующего по порядку изделия.
        # Снимаем выделение с только что добавленной строки: тогда
        # _current_product_prefix() возвращает len(saved_screens) + 1.
        try:
            self.saved_tree.selection_remove(self.saved_tree.selection())
            self.saved_tree.focus("")
        except Exception:
            pass
        # Кабинетные номера рисуются в _redraw_selection(), поэтому
        # после добавления изделия перерисовываем именно выбор/раскладку.
        # К этому моменту выделение сохранённой строки снято, и префикс
        # становится номером следующего изделия: len(saved_screens) + 1.
        self._redraw_selection()

        self._flash_project_button("✓ Добавлено в проект")

    def _flash_project_button(self, message):
        original = "＋  Добавить в проект"
        self.add_project_button.configure(text=message)
        self.after(1200, lambda: self.add_project_button.configure(text=original))

    def _load_saved_screen(self):
        selected = self.saved_tree.selection()
        if not selected:
            return
        index = int(selected[0])
        if index >= len(self.saved_screens):
            return

        self._sync_active_screen_from_form()
        screen = self.saved_screens[index]
        self._loading_saved_product=True
        self._active_screen_index=index
        mode = screen.get("mode", MODE_RZD)
        self.screen_mode_var.set(mode)
        self.screen_mode = mode
        if mode == MODE_MCD and hasattr(self, "mcd_size_var"):
            self.mcd_size_var.set(screen.get("mcd_size", "Нестандарт"))
            if self.mcd_size_var.get() == "Нестандарт":
                if not self.mcd_manual_frame.winfo_manager():
                    self.mcd_manual_frame.pack(fill="x", pady=(0,8))
            else:
                self.mcd_manual_frame.pack_forget()
        self._update_mode_ui()
        self._draw_grid()

        self.screen_article_var.set(screen.get("screen_article", ""))
        self.module_article_var.set(screen.get("module_article", ""))
        self.part_number_var.set(screen.get("part_number", ""))
        self.screen_environment_var.set(screen.get("environment", "Улица"))
        self._update_led_type_options()
        self.pixel_pitch_var.set(screen.get("pixel_pitch", "P2,5"))
        _lt=str(screen.get("led_type", "OD") or "OD").upper()
        self.led_type_var.set("ID" if _lt in ("I","IN","ID") else "OD")
        self._update_led_type_options()
        self.led_series_var.set(str(screen.get("led_series", screen.get("firmware", "")) or "")[:3])
        self.control_type_var.set(screen.get("control_type", "Встроенный Мини-ПК"))
        self.media_converter_var.set(bool(screen.get("media_converter", False)))
        self.optical_cross_var.set(bool(screen.get("optical_cross", False)))
        self.chip_var.set(screen.get("chip", ""))
        self.card_model_var.set(screen.get("card_model", "MRV416-N"))
        self.firmware_var.set(screen.get("firmware", ""))
        self.support_var.set(screen.get("support", ""))
        self.screen_quantity_var.set(str(screen.get("quantity", 1)))
        self.screen_sides_var.set(str(screen.get("sides", 1)))
        self.width_mm = screen.get("width", 0)
        self.height_mm = screen.get("height", 0)
        if mode == MODE_MCD and hasattr(self, "mcd_manual_width_var"):
            self.mcd_manual_width_var.set(str(self.width_mm))
            self.mcd_manual_height_var.set(str(self.height_mm))

        self.layout_index = 0
        self.side2_layout_index = int(screen.get("side2_layout_index", 0) or 0)
        self.side2_different_layout_var.set(bool(screen.get("side2_different_layout", False)))
        if mode == MODE_RZD:
            layouts = all_layouts(self.width_mm, self.height_mm)
            target_x = tuple(screen.get("width_parts", ()))
            target_y = tuple(screen.get("height_parts", ()))
            for i, (xs, ys) in enumerate(layouts):
                if tuple(xs) == target_x and tuple(ys) == target_y:
                    self.layout_index = i
                    break
        self._on_side2_option_changed()
        self._redraw_selection()
        self._loading_saved_product=False

    def _delete_saved_screen(self):
        selected = self.saved_tree.selection()
        if not selected:
            return

        old_index = int(selected[0])
        if old_index >= len(self.saved_screens):
            return

        del self.saved_screens[old_index]
        self._active_screen_index=None
        self._mark_project_dirty()

        self._rebuild_saved_screens_tree()
        self._refresh_project_journal()

        self._refresh_components_screen_selector()
        self._refresh_components_table()
        self._refresh_stock_screen_selector()
        self._refresh_procurement_table()

    def _refresh_components_screen_selector(self):
        if not hasattr(self, "component_scope_combo"):
            return
        values=["Весь проект"]
        for i,screen in enumerate(self.saved_screens,start=1):
            mode=screen.get("mode",MODE_RZD)
            product_type=("МЦД динамика" if mode==MODE_MCD else "РЖД динамика")
            sides=f"{int(screen.get('sides',1) or 1)} сторона" if int(screen.get('sides',1) or 1)==1 else f"{int(screen.get('sides',1) or 1)} стороны"
            size=f"{screen.get('width',0)}×{screen.get('height',0)}"
            pitch=str(screen.get("pixel_pitch","") or "").replace(",",".")
            values.append(f"LED {i} — {product_type}, {sides}, {size}, {pitch}")
        for i,sign in enumerate(getattr(self,"saved_static_signs",[]),start=1):
            mode=sign.get("mode",MODE_MCD)
            product_type=("МЦД статика" if mode==MODE_MCD else "РЖД статика")
            side_count=int(sign.get("sides",1) or 1)
            sides=f"{side_count} сторона" if side_count==1 else f"{side_count} стороны"
            size=(f"Ø{sign.get('width',0)}" if sign.get("round",False) else f"{sign.get('width',0)}×{sign.get('height',0)}")
            face=str(sign.get("face_type","") or "").lower()
            static_prefix=("МЦД" if mode==MODE_MCD else "РЖД")
            values.append(f"{static_prefix} {i} — {product_type}, {sides}, {size}, {face}")
        self.component_scope_combo["values"]=values
        if self.component_scope_var.get() not in values:self.component_scope_var.set("Весь проект")

    def _selected_component_items(self):
        selected=self.component_scope_var.get()
        if selected=="Весь проект":
            return list(self.saved_screens), list(getattr(self,"saved_static_signs",[]))
        if selected.startswith("LED "):
            try:i=int(selected.split(" ",2)[1])-1
            except Exception:return list(self.saved_screens),[]
            return ([self.saved_screens[i]] if 0<=i<len(self.saved_screens) else []),[]
        if selected.startswith("МЦД ") or selected.startswith("РЖД "):
            signs=getattr(self,"saved_static_signs",[])
            try:i=int(selected.split(" ",2)[1])-1
            except Exception:return [],signs
            return [],([signs[i]] if 0<=i<len(signs) else [])
        return list(self.saved_screens),list(getattr(self,"saved_static_signs",[]))

    def _selected_component_screens(self):
        return self._selected_component_items()[0]

    def _format_component_qty(self, value):
        if isinstance(value,str):return value
        if abs(value-round(value))<1e-9:return str(int(round(value)))
        return f"{value:.2f}".rstrip("0").rstrip(".")

    def _mcd_case_elements(self, width_mm, height_mm):
        """Расчёт составных элементов корпуса МЦД из профиля 75/120/175 мм.

        Обе стороны <= 2999 мм: 2 П-элемента.
        П-элемент: 1/2 короткой x длинная x 1/2 короткой.
        Если хотя бы одна сторона > 2999 мм: 4 Г-элемента; сохраняем
        прежнее деление обеих сторон пополам для четырёх угловых элементов.
        """
        w=max(0.0,float(width_mm)); h=max(0.0,float(height_mm))
        if w<=0 or h<=0:
            return None
        short=min(w,h); long=max(w,h)
        if w>2999 or h>2999:
            return ("Г-элемент",4,long/2.0,short/2.0)
        return ("П-элемент",2,long,short/2.0)

    def _mcd_case_component_row(self, width_mm, height_mm, profile_mm=None):
        data=self._mcd_case_elements(width_mm,height_mm)
        if not data:return None
        kind,qty,long_part,shelf=data
        def fmt(v):
            return str(int(round(v))) if abs(v-round(v))<1e-9 else f"{v:.1f}".rstrip("0").rstrip(".")
        prefix=f"Профиль {profile_mm}мм — " if profile_mm else ""
        if kind == "П-элемент":
            size=f"{fmt(shelf)}×{fmt(long_part)}×{fmt(shelf)} мм"
        else:
            size=f"{fmt(long_part)}×{fmt(shelf)} мм"
        return (f"{prefix}{kind} — {size}", "шт.", qty)

    def _draw_mcd_case_split(self, canvas, x1, y1, x2, y2, width_mm, height_mm, tags="cabinet"):
        """Пунктирная визуализация стыков П-/Г-элементов."""
        if width_mm>2999 or height_mm>2999:
            canvas.create_line((x1+x2)/2,y1,(x1+x2)/2,y2,fill="#725b00",dash=(7,5),width=2,tags=tags)
            canvas.create_line(x1,(y1+y2)/2,x2,(y1+y2)/2,fill="#725b00",dash=(7,5),width=2,tags=tags)
            canvas.create_text((x1+x2)/2,(y1+y2)/2,text="  4 × Г-элемент",anchor="nw",
                               fill="#725b00",font=("Arial",8,"bold"),tags=tags)
        else:
            # Для двух П-элементов делим именно КОРОТКУЮ сторону изделия пополам.
            # Горизонтальное изделие (W >= H): короткая сторона = высота,
            # поэтому линия стыка горизонтальная на H/2.
            # Вертикальное изделие (H > W): короткая сторона = ширина,
            # поэтому линия стыка вертикальная на W/2.
            if width_mm>=height_mm:
                ym=(y1+y2)/2
                canvas.create_line(x1,ym,x2,ym,fill="#725b00",dash=(7,5),width=2,tags=tags)
                canvas.create_text((x1+x2)/2,ym,text="2 × П-элемент  ",anchor="s",
                                   fill="#725b00",font=("Arial",8,"bold"),tags=tags)
            else:
                xm=(x1+x2)/2
                canvas.create_line(xm,y1,xm,y2,fill="#725b00",dash=(7,5),width=2,tags=tags)
                canvas.create_text(xm,(y1+y2)/2,text="  2 × П-элемент",anchor="w",
                                   fill="#725b00",font=("Arial",8,"bold"),tags=tags)

    def _static_mcd_power_supplies(self, clean_power):
        """Подбор БП по суммарной мощности LED без дополнительного запаса.

        Номиналы из справочника: 25/40/60/100/150 Вт. Сначала выбирается
        минимальное количество блоков, достаточное по мощности; среди вариантов
        с тем же количеством — минимальная суммарная установленная мощность.
        """
        import itertools
        allowed=(25,40,60,100,150)
        required=max(0.0,float(clean_power))
        result={p:0 for p in allowed}
        if required<=1e-9:
            return result
        min_count=max(1,int(math.ceil(required/max(allowed))))
        best=None
        for count in range(min_count, min_count+len(allowed)+1):
            candidates=[]
            for combo in itertools.combinations_with_replacement(allowed,count):
                capacity=sum(combo)
                if capacity+1e-9>=required:
                    candidates.append((capacity,combo))
            if candidates:
                best=min(candidates,key=lambda x:(x[0],tuple(-v for v in sorted(x[1],reverse=True))))[1]
                break
        if best is None:
            return result
        for nominal in best:
            result[nominal]+=1
        return result

    def _static_mcd_component_rows(self, signs):
        """Комплектующие МЦД с подсветкой по актуальному справочнику.

        Поддерживаются 1- и 2-сторонние изделия.
        Электрический расчёт: для любого статического МЦД с подсветкой суммарная мощность LED × 1,20, затем подбор БП 25/40/60/100/150 Вт.
        """
        rows={}
        def add(name,unit,qty):
            if qty is None:return
            key=(name,unit); rows[key]=rows.get(key,0)+qty

        def m4_per_two_horizontal_sides(width_mm):
            # Справочник: на сторону 1 м→2; 2 м→3; 3 м→4, минимум 2.
            per_side=max(2,math.ceil(max(0.0,width_mm)/1000.0)+1)
            return per_side*2

        for s in signs:
            if s.get("mode")!=MODE_MCD or s.get("face_type")!="С подсветкой":
                continue
            w=float(s.get("width",0)); h=float(s.get("height",0))
            sides=int(s.get("sides",1))
            if w<=0 or h<=0:continue
            perimeter=2.0*(w+h)/1000.0

            if not bool(s.get("round",False)):
                profile_mm = 120 if sides == 2 else 75
                case_row=self._mcd_case_component_row(w,h,profile_mm)
                if case_row:add(*case_row)

            if sides==2:
                # Закупочное количество: ceil(ширина / 65 мм) × 2 (две стороны).
                led_buy=math.ceil(w/65.0)*2
                # Для электрического расчёта: 12 LED/м на верхней и нижней горизонтали.
                led_installed=math.ceil((w/1000.0)*12.0)*2
                clean_power=led_installed*1.5
                design_power=clean_power*1.20
                psus=self._static_mcd_power_supplies(design_power)
                psu_count=sum(psus.values())

                add("Торцевой светодиод 50×25 мм, 1,5 Вт","шт.",led_buy)
                add("Саморез острый (клоп)  3,5×9,5 мм","шт.",led_buy*2)
                add("Соединитель проводов WAGO 2-полюсный","шт.",psu_count)
                add("Соединитель проводов WAGO 3-полюсный","шт.",1)
                for nominal,count in psus.items():
                    if count:add(f"Блок питания {nominal} Вт","шт.",count)

                # ШВВП: по справочнику v2 отдельный 2-метровый провод для остаточной
                # группы 1–19 LED после формирования полных групп по 20.
                remainder=led_installed%20
                add("Провод ШВВП 2×0,75 мм²","м",2 if remainder else 0)

                # V19.99 / справочник v2: уголок по периметру уменьшенного габарита (W−50) × (H−50).
                angle_w=max(0.0,w-50.0); angle_h=max(0.0,h-50.0)
                angle_len=2.0*(angle_w+angle_h)/1000.0
                add("Уголок алюминиевый 30×20×2 мм","м.п.",angle_len)
                add("Уплотнитель резиновый коричневый","м.п.",perimeter*2)
                add("Скотч двухсторонний 3M","м.п.",angle_len)
                add("Праймер","г",2.5*angle_len)

                m4=m4_per_two_horizontal_sides(w)
                add("Саморез оконный 3,9×25 мм","шт.",m4)
                add("Заклёпка резьбовая М4","шт.",m4)
                add("Заглушка пластиковая декоративная 12","шт.",m4)

                add("Заклёпка вытяжная алюминиевая 4,8×12 мм","шт.",36)
                add("Монтажная пластина металлическая 80×13×2 мм","шт.",4)
                add("Герметик силиконовый бесцветный прозрачный","г",30)
                add("Термоусадочная трубка","м",0.30)
                add("Клей космофен","г",3)
                glass_w=max(0,w-18); glass_h=max(0,h-18)
                add(f"Оргстекло 8 мм {self._format_component_qty(glass_w)}×{self._format_component_qty(glass_h)} мм, R66","шт.",2)

                # Для двухстороннего изделия шириной от 1999 мм:
                # одна перемычка-шпилька М10 длиной в высоту изделия.
                if w>=1999:
                    add("Перемычка — шпилька М10","м",h/1000.0)
                    add("Резьбовая заклёпка для шпильки M10","шт.",2)
                    add("Площадка для шпильки 80×40×5 мм","шт.",2)
                    add("Заклёпка вытяжная алюминиевая 4,8×12 мм для шпильки","шт.",8)

                add("LED фактически установлено (для расчёта мощности)","шт.",led_installed)
                add("Расчётная мощность LED (+20%)","Вт",design_power)

            elif sides==1:
                led_cols=math.ceil((w/1000.0)*6.0)
                led_rows=math.ceil((h/800.0)*7.0)
                led_count=led_cols*led_rows
                clean_power=led_count*1.5
                design_power=clean_power*1.20
                psus=self._static_mcd_power_supplies(design_power)
                psu_count=sum(psus.values())
                add("Фронтальный светодиод 70×15 мм, 1,5 Вт","шт.",led_count)
                add("Саморез универсальный 3×10 мм","шт.",led_count*2)
                add("Соединитель проводов WAGO 2-полюсный","шт.",psu_count)
                add("Соединитель проводов WAGO 3-полюсный","шт.",1)
                for nominal,count in psus.items():
                    if count:add(f"Блок питания {nominal} Вт","шт.",count)
                if led_count%20:
                    add("Провод ШВВП 2×0,75 мм²","м",2)
                # Уголок: каждую сторону уменьшаем на 180 мм, затем удвоенный суммарный периметр.
                aw=max(0.0,w-180.0); ah=max(0.0,h-180.0)
                angle_len=2.0*(aw+ah)/1000.0
                angle_len*=2.0  # V19.87: односторонний МЦД статика — расчёт уголка ×2
                add("Уголок алюминиевый 30×20×2 мм","м.п.",angle_len)
                add("Уплотнитель резиновый коричневый","м.п.",perimeter)
                # М4 по всем четырём сторонам: ceil(L м)+1, минимум 2 на сторону.
                per_w=max(2,math.ceil(w/1000.0)+1); per_h=max(2,math.ceil(h/1000.0)+1)
                m4=2*per_w+2*per_h
                add("Саморез оконный 3,9×25 мм","шт.",m4)
                add("Заклёпка резьбовая М4","шт.",m4)
                add("Заглушка пластиковая декоративная 12","шт.",m4)
                is_g=(w>2999 or h>2999)
                add("Заклёпка вытяжная алюминиевая 4,8×12 мм","шт.",72 if is_g else 36)
                add("Монтажная пластина металлическая 80×13×2 мм","шт.",4 if is_g else 2)
                # На стенку: 1 клёпка на 150 мм уголка, минимум 2 на каждую сторону.
                wall=2*max(2,math.ceil(aw/150.0))+2*max(2,math.ceil(ah/150.0))
                add("Заклёпка вытяжная алюминиевая 4,8×10 мм на стенку","шт.",wall)
                add("Герметик силиконовый бесцветный прозрачный","г",30)
                add("Термоусадочная трубка","м",0.30)
                add("Скотч фольгированный","м",0.4*psu_count)
                tape=angle_len/2.0+0.4  # V19.88: 3M = итоговая длина уголка / 2 + 0,4 м на БП
                add("Скотч двухсторонний 3M","м",tape)
                add("Праймер","г",2.5*tape)
                add("Наконечник 0,75 мм²","шт.",4)
                add("Клей космофен","г",3)
                # V19.87 — оргстекло для любого МЦД: (W−18) × (H−18).
                glass_w=max(0,w-18); glass_h=max(0,h-18)
                add(f"Оргстекло 8 мм {self._format_component_qty(glass_w)}×{self._format_component_qty(glass_h)} мм, R66","шт.",1)
                # Односторонняя статика МЦД: задняя крышка из алюкобонда остаётся (W−52) × (H−52), R49.
                back_w=max(0,w-52); back_h=max(0,h-52)
                add(f"Алюкобонд 3 мм {self._format_component_qty(back_w)}×{self._format_component_qty(back_h)} мм, R49","шт.",1)
                add("LED фактически установлено (для расчёта мощности)","шт.",led_count)
                add("Расчётная мощность LED (+20%)","Вт",design_power)

        return [(name,unit,qty) for (name,unit),qty in rows.items()]

    def _reference_group_for_component(self, name):
        n=str(name).lower()

        # Расходные материалы проверяем первыми, чтобы скотч/герметик/клей
        # не попадали в соседние группы по случайным словам.
        if any(k in n for k in ("герметик","космофен","клей","скотч","праймер","уплотнитель","термоусад")):
            return "Герметики, клеи и прочее"

        # 1. Электроника
        if any(k in n for k in (
            "модули", "модуль", "led", "светодиод", "бп", "блок питания",
            "мрв", "приёмная карта", "приемная карта", "novastar", "msd", "карта msd",
            "мини-пк", "rassberry", "raspberry", "вентилятор", "термодатчик", "медиаконвертер", "кросс"
        )):
            return "Электроника"

        # 2. Металлические комплектующие
        if any(k in n for k in (
            "профиль", "профильная труба", "уголок перфор", "алюкобонд",
            "площадк", "пластина", "уголок алюминиев", "решетки на кабинеты", "решётки на кабинеты",
            "din-рейка", "din рейка", "шпилька"
        )):
            return "Металлические комплектующие"

        # 3. Электрика
        if any(k in n for k in (
            "кабель", "провод", "wago", "наконечник", "utp", "rj-45", "rj45",
            "вилка+розетка", "powercon", "пвс", "кгхл", "шввп", "ввг", "клеммная колодка",
            "dvi-hdmi", "hdmi", "bls1"
        )):
            return "Электрика"

        # 4. Крепёж и метизы
        if any(k in n for k in (
            "саморез", "винт", "болт", "гайка", "шайба", "закл",
            "заглушка", "замок"
        )):
            return "Крепёж и метизы"

        # 5. Герметики, клеи и прочее
        return "Герметики, клеи и прочее"

    def _reference_led_cabinet_rows(self, cabinet_size):
        """Полный справочник одного LED-кабинета из тех же норм,
        которые реально используются калькулятором COMPONENT_RATES."""
        rates = COMPONENT_RATES[cabinet_size]
        rows=[]
        size_label=f"{cabinet_size[0]}×{cabinet_size[1]}"

        pretty = {
            "Кабинеты": "Кабинет",
            "Модули": "LED-модуль",
            "БП": "Блок питания",
            "МРВ": "Приёмная карта NovaStar MRV416-N",
        }
        special_logic = {
            "Кабинеты": f"Один кабинет типоразмера {size_label}.",
            "Модули": f"Фиксированная норма LED-модулей на один кабинет {size_label}.",
            "БП": f"Фиксированная норма блоков питания на один кабинет {size_label}.",
            "МРВ": "Одна приёмная карта на кабинет.",
            "DIN-рейка": "Одна DIN-рейка длиной 10 см на каждый кабинет.",
        }

        for key, qty in rates.items():
            name=pretty.get(key,key)
            logic=special_logic.get(key, f"Фиксированная норма на один кабинет {size_label}.")
            unit=COMPONENT_UNITS.get(key,"шт.")
            if isinstance(qty,float):
                qtext=(f"{qty:.2f}".rstrip("0").rstrip(".")).replace(".",",")
            else:
                qtext=str(qty)
            rows.append([name,logic,qtext,unit])
        return rows

