    def _reference_load(self):
        data=self._reference_defaults()
        self._reference_history=[]
        try:
            p=self._reference_file()
            if p.exists():
                saved=json.loads(p.read_text(encoding="utf-8"))
                data.update(saved.get("sections",{}))
                # V20.04: точечная миграция старого локального справочника.
                # Только МЦД, статика, 1 сторона, с подсветкой: 2,5×12 -> 3×10.
                sec="МЦД / 1 сторона / с подсветкой"
                for row in data.get(sec,[]):
                    if row and str(row[0]).strip()=="Саморез универсальный 2,5×12 мм":
                        row[0]="Саморез универсальный 3×10 мм"
                        if len(row)>=5:
                            row[4]=""  # вес 3×10 пока не подтверждён
                self._reference_history=saved.get("history",[])

                # V20.09: миграция РЖД — молочный акрил 4 мм, алюкобонд 4 мм,
                # отсутствие алюкобонда у двухсторонних изделий.
                def _upsert_rzd_row(sec, name, rule, qty, unit, weight=""):
                    rows=data.setdefault(sec,[])
                    # Удаляем старые варианты той же позиции.
                    aliases={name}
                    if name=="Молочный Акрил 4 мм": aliases.update({"Оргстекло","Оргстекло 4 мм","Молочный акрил 4 мм"})
                    if name=="Алюкобонд 4 мм": aliases.update({"Алюкобонд на стенку","Алюкобонд 3 мм"})
                    hit=None
                    cleaned=[]
                    for row in rows:
                        if row and str(row[0]).strip() in aliases:
                            if hit is None:
                                hit=[name,rule,qty,unit,weight]
                            continue
                        cleaned.append(row)
                    if hit is None: hit=[name,rule,qty,unit,weight]
                    # Добавляем материал после заголовка металлических комплектующих, если возможно.
                    pos=next((i+1 for i,r in enumerate(cleaned) if r and str(r[0]).strip()=="Металлические комплектующие"),len(cleaned))
                    cleaned.insert(pos,hit)
                    data[sec]=cleaned

                _upsert_rzd_row("РЖД / 1 сторона / с подсветкой","Молочный Акрил 4 мм","1 шт.; размер = (W − 10) × (H − 10) мм.","1","шт.")
                _upsert_rzd_row("РЖД / 2 стороны / с подсветкой","Молочный Акрил 4 мм","2 шт.; размер каждого = (W − 10) × (H − 10) мм.","2","шт.")
                _upsert_rzd_row("РЖД / 1 сторона / с подсветкой","Алюкобонд 4 мм","1 шт.; размер = (W − 5) × (H − 5) мм.","1","шт.")
                _upsert_rzd_row("РЖД / 1 сторона / без подсветки","Алюкобонд 4 мм","1 шт.; размер = (W − 5) × (H − 5) мм.","1","шт.")
                for sec in ("РЖД / 2 стороны / с подсветкой","РЖД / 2 стороны / без подсветки","РЖД / 2 стороны / светоотражающий"):
                    data[sec]=[r for r in data.get(sec,[]) if not (r and "Алюкобонд" in str(r[0]))]
        except Exception as e: print("Reference load:",e)
        # Те же правила должны действовать и на чистом встроенном справочнике.
        def _ensure_rzd_material(sec, name, rule, qty, unit, aliases=()):
            rows=data.setdefault(sec,[])
            all_aliases=set(aliases)|{name}
            rows=[r for r in rows if not (r and str(r[0]).strip() in all_aliases)]
            pos=next((i+1 for i,r in enumerate(rows) if r and str(r[0]).strip()=="Металлические комплектующие"),len(rows))
            rows.insert(pos,[name,rule,qty,unit,""])
            data[sec]=rows
        _ensure_rzd_material("РЖД / 1 сторона / с подсветкой","Молочный Акрил 4 мм","1 шт.; размер = (W − 10) × (H − 10) мм.","1","шт.",("Оргстекло","Оргстекло 4 мм","Молочный акрил 4 мм"))
        _ensure_rzd_material("РЖД / 2 стороны / с подсветкой","Молочный Акрил 4 мм","2 шт.; размер каждого = (W − 10) × (H − 10) мм.","2","шт.",("Оргстекло","Оргстекло 4 мм","Молочный акрил 4 мм"))
        _ensure_rzd_material("РЖД / 1 сторона / с подсветкой","Алюкобонд 4 мм","1 шт.; размер = (W − 5) × (H − 5) мм.","1","шт.",("Алюкобонд на стенку","Алюкобонд 3 мм"))
        _ensure_rzd_material("РЖД / 1 сторона / без подсветки","Алюкобонд 4 мм","1 шт.; размер = (W − 5) × (H − 5) мм.","1","шт.",("Алюкобонд на стенку","Алюкобонд 3 мм"))
        for sec in ("РЖД / 2 стороны / с подсветкой","РЖД / 2 стороны / без подсветки","РЖД / 2 стороны / светоотражающий"):
            data[sec]=[r for r in data.get(sec,[]) if not (r and "Алюкобонд" in str(r[0]))]
        return data

    def _reference_save(self):
        self._reference_file().write_text(json.dumps({"sections":self._reference_data,
            "history":self._reference_history},ensure_ascii=False,indent=2),encoding="utf-8")

    def _reference_refresh(self):
        if not hasattr(self,"reference_tree"):return
        self.reference_tree.delete(*self.reference_tree.get_children())
        sec=self.reference_section_var.get()
        group_order=[
            "Электроника",
            "Металлические комплектующие",
            "Электрика",
            "Крепёж и метизы",
            "Герметики, клеи и прочее",
        ]
        rows=self._reference_data.get(sec,[])
        grouped={g:[] for g in group_order}
        for i,row in enumerate(rows):
            grouped.setdefault(self._reference_group_for_component(row[0] if row else ""),[]).append((i,row))
        for gi,group in enumerate(group_order):
            items=grouped.get(group,[])
            if not items:
                continue
            parent=f"group_{gi}"
            self.reference_tree.insert("","end",iid=parent,text=group,values=("","","","",""),open=True,
                                       tags=("reference_group",))
            for i,row in items:
                self.reference_tree.insert(parent,"end",iid=f"row_{i}",text="",values=list(row))
        self.reference_tree.tag_configure("reference_group",font=("Arial",10,"bold"),
                                          background="#e8eef5",foreground="#1f2d3d")
        dates=[h.get("date","") for h in self._reference_history if h.get("section")==sec]
        self.reference_changed_label.configure(text=("Последняя корректировка: "+dates[-1] if dates else "Без пользовательских корректировок"))

    def _reference_edit_cell(self,event):
        if not self.reference_edit_var.get():return
        if self.reference_tree.identify_region(event.x,event.y)!="cell":return
        rowid=self.reference_tree.identify_row(event.y); colid=self.reference_tree.identify_column(event.x)
        if not rowid or not colid or not rowid.startswith("row_"):return
        ci=int(colid[1:])-1
        if ci < 0:return
        data_ci=ci
        bbox=self.reference_tree.bbox(rowid,colid)
        if not bbox:return
        x,y,w,h=bbox; old=self.reference_tree.item(rowid,"values")[ci]
        ed=ttk.Entry(self.reference_tree); ed.insert(0,old); ed.select_range(0,"end")
        ed.place(x=x,y=y,width=w,height=h); ed.focus_set()
        done=[False]
        def commit(_=None):
            if done[0]:return
            done[0]=True; new=ed.get().strip(); ed.destroy()
            if new==str(old):return
            sec=self.reference_section_var.get(); ri=int(rowid.split("_",1)[1])
            self._reference_data[sec][ri][data_ci]=new
            stamp=datetime.now().strftime("%d.%m.%Y %H:%M")
            self._reference_history.append({"date":stamp,"section":sec,"row":ri,"column":data_ci,"old":old,"new":new})
            try:self._reference_save()
            except Exception as e:messagebox.showerror("Справочник",f"Не удалось сохранить корректировку:\\n{e}")
            self._reference_refresh()
        ed.bind("<Return>",commit); ed.bind("<FocusOut>",commit)
        ed.bind("<Escape>",lambda e:(done.__setitem__(0,True),ed.destroy()))

    def _static_rzd_component_rows(self, signs):
        """РЖД BOM по актуальному справочнику из 6 листов.
        Для 2-стороннего с подсветкой количество LED считается по утверждённой
        логике МЦД: закупка ceil(ширина / 65 мм) × 2, монтаж/мощность по 12 LED/м.п. × 2.
        """
        rows={}
        def add(name,unit,qty):
            if qty is None or abs(float(qty)) < 1e-12:return
            rows[(name,unit)]=rows.get((name,unit),0)+qty
        def perimeter(w,h): return 2*(w+h)/1000.0
        def tube_40x20_len(w,h):
            return (2*max(0.0, w-4.0) + 2*max(0.0, h-44.0))/1000.0
        def perim_fasteners(w,h,step):
            return 2*max(2,math.ceil(w/step))+2*max(2,math.ceil(h/step))

        for s in signs:
            if s.get("mode")!=MODE_RZD: continue
            w=float(s.get("width",0)); h=float(s.get("height",0))
            sides=int(s.get("sides",1)); face=s.get("face_type","С подсветкой")
            if w<=0 or h<=0: continue
            per=perimeter(w,h); tube_len=tube_40x20_len(w,h)
            acrylic_area=max(0.0,w-10.0)*max(0.0,h-10.0)/1_000_000.0
            aluc_area=max(0.0,w-5.0)*max(0.0,h-5.0)/1_000_000.0

            if face=="С подсветкой" and sides==2:
                led_purchase=math.ceil(w/65.0)*2
                led_installed=math.ceil((w/1000.0)*12.0)*2
                clean=led_installed*1.5
                design_power=clean*1.20
                psus=self._static_mcd_power_supplies(design_power)
                psu_count=sum(psus.values())

                add("Уголок перфорированный 70×70×40","шт.",4)
                add("Торцевой светодиод 50×25 мм, 1,5 Вт","шт.",led_purchase)
                add("Молочный Акрил 4 мм","м²",acrylic_area*2)
                add("Термоусадочная трубка","м",0.30)
                add("Соединитель проводов WAGO 3-полюсный","шт.",1)
                add("Соединитель проводов WAGO 2-полюсный","шт.",psu_count)
                add("Саморез универсальный 3×12 мм белый цинк потай","шт.",perim_fasteners(w,h,400.0))
                add("Саморез ПШ 4,2×12 с буром","шт.",led_purchase*2+32)
                add("Профильная труба алюминиевая 40×20×2 мм","м.п.",tube_len)
                add("Профиль алюминиевый П-образный 60×20×2 мм","м.п.",per)
                # По листу: 2 м только при остаточной группе 1–19 LED.
                if led_installed % 20:
                    add("Провод ШВВП 2×0,75 мм²","м",2)
                add("Клей космофен","г",3)
                add("Герметик силиконовый бесцветный прозрачный","г",30)
                for nominal,count in psus.items():
                    add(f"Блок питания {nominal} Вт","шт.",count)

                # Сохраняем ранее утверждённую пользователем границу:
                # перемычка для двухстороннего указателя начиная с 1999 мм.
                if w>=1999:
                    add("Перемычка — шпилька М10","м",h/1000.0)
                    add("Резьбовая заклёпка для шпильки M10","шт.",2)

                add("Установлено LED (для расчёта мощности)","шт.",led_installed)
                add("Расчётная мощность LED (+20%)","Вт",design_power)

            elif face=="С подсветкой" and sides==1:
                cols=math.ceil((w/1000.0)*6.0)
                led_rows=math.ceil((h/800.0)*7.0)
                led=cols*led_rows
                clean=led*1.5
                design_power=clean*1.20
                psus=self._static_mcd_power_supplies(design_power)
                psu_count=sum(psus.values())

                add("Фронтальный светодиод 70×15 мм, 1,5 Вт","шт.",led)
                add("Молочный Акрил 4 мм","м²",acrylic_area)
                add("Уголок перфорированный 70×70×40","шт.",4)
                add("Термоусадочная трубка","м",0.30)
                add("Соединитель проводов WAGO 3-полюсный","шт.",1)
                add("Соединитель проводов WAGO 2-полюсный","шт.",psu_count)
                add("Скотч двухсторонний 3M","м",0.4*psu_count)
                add("Саморез универсальный 3×12 мм белый цинк потай","шт.",perim_fasteners(w,h,400.0)+led*2)
                add("Саморез ПШ 4,2×12 с буром","шт.",32)
                add("Саморез оконный 3,9×25 мм","шт.",perim_fasteners(w,h,150.0))
                add("Профиль алюминиевый П-образный 60×20×2 мм","м.п.",per)
                add("Профильная труба алюминиевая 40×20×2 мм","м.п.",tube_len)
                if led % 20:
                    add("Провод ШВВП 2×0,75 мм²","м",2)
                add("Провод ПВС 3×1,5 мм²","м",2)
                add("Наконечник 1,5 мм²","шт.",6)
                add("Клей космофен","г",3)
                add("Фольгированный скотч","м",0.4*psu_count)
                add("Герметик силиконовый бесцветный прозрачный","г",30)
                for nominal,count in psus.items():
                    add(f"Блок питания {nominal} Вт","шт.",count)
                add("Алюкобонд 4 мм","м²",aluc_area)
                add("Установлено LED (для расчёта мощности)","шт.",led)
                add("Расчётная мощность LED (+20%)","Вт",design_power)

            elif face in ("Без подсветки","Светоотражающее"):
                add("Профиль алюминиевый П-образный 60×20×2 мм","м.п.",per)
                add("Профильная труба алюминиевая 40×20×2 мм","м.п.",tube_len)
                add("Уголок перфорированный 70×70×40","шт.",4)
                add("Саморез ПШ 4,2×12","шт.",32)
                add("Саморез универсальный 3×12 мм белый цинк потай","шт.",perim_fasteners(w,h,400.0))
                if sides==1:
                    if face=="Без подсветки":
                        add("Алюкобонд 4 мм","м²",aluc_area)
                    add("Саморез универсальный 3×12 мм белый цинк потай на стенку","шт.",perim_fasteners(w,h,150.0))

        return [(n,u,q) for (n,u),q in rows.items()]

    def _selected_led_module_name(self, screen):
        """Возвращает точное название LED-модуля из первых трёх листов справочника."""
        pitch = str(screen.get("pixel_pitch", "") or "").strip()
        led_type = str(screen.get("led_type", "OD") or "OD").strip().upper()
        return LED_MODULE_REFERENCE_NAMES.get((pitch, led_type))

    def _mcd_module_pixel_resolution(self, screen):
        """Разрешение одного MCD LED-модуля 320×160 мм для выбранного шага."""
        raw=str(screen.get("pixel_pitch","") or "").upper().replace("P","").replace(",",".").strip()
        try:
            pitch=float(raw)
        except (TypeError,ValueError):
            return (0,0)
        if pitch<=0:
            return (0,0)
        return (max(1,int(round(MCD_MODULE_W/pitch))),
                max(1,int(round(MCD_MODULE_H/pitch))))

    def _mcd_mrv_count_per_face(self, screen):
        """MRV на одну сторону = ceil(Wpx/256) × ceil(Hpx/256)."""
        px_w,px_h=self._mcd_module_pixel_resolution(screen)
        if not px_w or not px_h:
            return 0
        w=float(screen.get("width",0) or 0)
        h=float(screen.get("height",0) or 0)
        per_face=int(screen.get("module_total",0) or 0)
        # MCD-модули 320×160; для обычного MCD поле имеет технологический отступ 50 мм.
        cols=max(1,int((w-2*MCD_MARGIN)//MCD_MODULE_W))
        rows=max(1,int((h-2*MCD_MARGIN)//MCD_MODULE_H))
        if cols*rows!=per_face and per_face>0:
            # Для нестандартного размера раскладка строится непосредственно от габарита.
            c2=max(1,int(w//MCD_MODULE_W)); r2=max(1,int(h//MCD_MODULE_H))
            if c2*r2==per_face:
                cols,rows=c2,r2
            else:
                rows=max(1,int(math.ceil(per_face/cols)))
        side_px_w=cols*px_w
        side_px_h=rows*px_h
        return int(math.ceil(side_px_w/256.0)*math.ceil(side_px_h/256.0))

