            add("Вентилятор с решеткой","шт",fans); add("площадка под вентилятор мцд","шт",fans)
            add("Площадки под блоки мцд","шт",psu); add("Din рейка","шт",qprod)
            angle=2*(max(0,w-180)+max(0,h-180))/1000.0*qprod
            add("уголок алюминиевый 40х20х2","м",angle)

            # V19.75 — профиль Гефест для динамического МЦД:
            # только при высоте > 740 мм; длина = высоте изделия;
